use vstd::prelude::*;

verus! {

// Spec function to normalize integer angle (in degrees) to [0,360).
spec fn norm_360(x: int) -> int {
    let m := x % 360;
    if m < 0 { m + 360 } else { m }
}

// Spec function that computes deviation from vertical given angle A in [0,360).
// The deviation is min(A, 360 - A), in [0,180].
spec fn deviation_from_vertical(A: int) -> int {
    if A <= 180 { A } else { 360 - A }
}

// Spec function that computes the deviation after r quarter-turn rotations,
// given input angle x as i8 (converted to int for arithmetic).
// Angle after rotation is normalized as:
// A = norm_360(-x + 90*r)
spec fn deviation_after_r(x: int, r: nat) -> int {
    deviation_from_vertical(norm_360(-x + 90 * (r as int)))
}

// Main function spec:
// Given x: i8 input angle,
// returns result: u8 with 0 <= result <= 3,
// such that for all k in {0,1,2,3}:
//   deviation_after_r(x, result) <= deviation_after_r(x, k), and
//   if equal, result <= k (tie-break to smallest r).
fn solve(x: i8) -> (result: u8)
    ensures
        result <= 3 &&
        forall(|k: u8| k <= 3 ==>
            let dk := deviation_after_r(x as int, k as nat);
            let dr := deviation_after_r(x as int, result as nat);
            dr <= dk &&
            (dr == dk ==> result <= k)
        )
{
    // Compute the deviation values for r in [0..3]
    let x_int: int = x as int;

    let mut best_r: u8 = 0;
    let mut best_dev: int = deviation_after_r(x_int, 0);

    let mut r: u8 = 1;
    while r <= 3
        invariant r <= 4,
        invariant best_r < 4,
        invariant best_dev == deviation_after_r(x_int, best_r as nat),
        decreases 4 - r,
    {
        let candidate_dev = deviation_after_r(x_int, r as nat);
        if candidate_dev < best_dev {
            best_dev = candidate_dev;
            best_r = r;
        }
        // If candidate_dev == best_dev, keep best_r (tie-break to smaller r)
        r += 1;
    }

    best_r
}

}
